function makeThrottled(fn, ms) {
  let last = 0;
  return function (...args) {
    let pending = null;
    const now = Date.now();
    if (now - last >= ms) {
      last = now;
      return fn(...args);
    }
    if (!pending) {
      pending = setTimeout(() => {
        last = Date.now();
        fn(...args);
      }, ms - (now - last));
    }
  };
}

