import itertools

def count_events_per_host(lines):
    parsed = (line.strip().split(",") for line in lines)
    groups = {}
    for host, events in itertools.groupby(parsed, key=lambda row: row[0]):
        groups[host] = events
    return {host: len(list(events)) for host, events in groups.items()}

